const emp = $input.first().json || {};
const ext = $('Extraer datos de la solicitud').first().json.output || {};
const PROJECT = 'proyecto atlas';

function pad(n) { return String(n).padStart(2, '0'); }
function toIso(v) {
  if (!v) return null;
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return m[1] + '-' + pad(+m[2]) + '-' + pad(+m[3]);
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);
  if (m) return m[3] + '-' + pad(+m[2]) + '-' + pad(+m[1]);
  return null;
}

const found = emp.employee_id !== undefined && emp.employee_id !== null && !!emp.email;
const isAtlas = found && String(emp.current_project || '').trim().toLowerCase() === PROJECT;
const reqStart = toIso(ext.start_date);
const reqEnd = toIso(ext.end_date);
const datesOk = ext.dates_certain === true && !!reqStart && !!reqEnd && reqStart <= reqEnd;

let overlaps = false;
let restrictedStart = null;
let restrictedEnd = null;
if (isAtlas && datesOk) {
  const y1 = Number(reqStart.slice(0, 4));
  const y2 = Number(reqEnd.slice(0, 4));
  for (let y = y1; y <= y2; y++) {
    const rs = y + '-12-01';
    const re = y + '-12-18';
    if (reqStart <= re && reqEnd >= rs) { overlaps = true; restrictedStart = rs; restrictedEnd = re; break; }
  }
}

return [{ json: {
  ...emp,
  atlas_restriction: {
    applies: isAtlas && overlaps,
    is_atlas_member: isAtlas,
    employee_found: found,
    dates_ok: datesOk,
    requested_start: reqStart,
    requested_end: reqEnd,
    restricted_start: restrictedStart,
    restricted_end: restrictedEnd,
  },
} }];

const req = $('Normalizar correo').first().json;
const ext = $('Extraer datos de la solicitud').first().json.output || {};
const empRaw = $('Buscar empleado por email').first().json || {};
const employee = (empRaw.employee_id !== undefined && empRaw.employee_id !== null && empRaw.email) ? empRaw : null;
const ownEmail = String(employee ? employee.email : req.sender_email || '').trim().toLowerCase();

const peers = employee
  ? $('Buscar compañeros mismo perfil').all().map(i => i.json)
      .filter(p => p && p.email && String(p.email).trim().toLowerCase() !== ownEmail)
  : [];
const rows = $('Leer vacaciones Google Sheets').all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);

function pad(n) { return String(n).padStart(2, '0'); }
function valid(y, mo, d) {
  const dt = new Date(Date.UTC(y, mo - 1, d));
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) return null;
  return y + '-' + pad(mo) + '-' + pad(d);
}
function toIso(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number' && isFinite(v)) {
    const d = new Date(Math.round((v - 25569) * 86400000));
    return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return valid(+m[1], +m[2], +m[3]);
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);
  if (m) return valid(+m[3], +m[2], +m[1]);
  if (/^\d+(\.\d+)?$/.test(s)) return toIso(Number(s));
  return null;
}
function statusClass(s) {
  const v = String(s || '').trim().toLowerCase();
  if (['approved', 'aprobado', 'aprobada', 'aprobadas'].includes(v)) return 'active';
  if (['pending', 'pendiente'].includes(v)) return 'active';
  if (['rejected', 'rechazado', 'rechazada', 'cancelled', 'canceled', 'cancelado', 'cancelada'].includes(v)) return 'ignored';
  return 'unknown';
}

const reqStart = toIso(ext.start_date);
const reqEnd = toIso(ext.end_date);
const datesOk = ext.dates_certain === true && !!reqStart && !!reqEnd && reqStart <= reqEnd;

const peerResults = peers.map(p => {
  const pEmail = String(p.email).trim().toLowerCase();
  const own = rows.filter(r => String(r.email || '').trim().toLowerCase() === pEmail);
  const conflicts = [];
  const ambiguous = [];
  for (const r of own) {
    const cls = statusClass(r.status);
    if (cls === 'ignored') continue;
    const s = toIso(r.start_date);
    const e = toIso(r.end_date);
    if (!s || !e || s > e) { ambiguous.push({ row: r, reason: 'fechas no válidas en la hoja de vacaciones' }); continue; }
    if (!datesOk) continue;
    const overlaps = s <= reqEnd && e >= reqStart;
    if (!overlaps) continue;
    if (cls === 'unknown') { ambiguous.push({ row: r, reason: 'estado desconocido: ' + r.status }); continue; }
    conflicts.push({
      employee: p.name, email: p.email, start_date: s, end_date: e, status: String(r.status).trim().toLowerCase(),
    });
  }
  let coverageStatus = 'available';
  if (conflicts.length > 0) coverageStatus = 'on_vacation_overlap';
  else if (ambiguous.length > 0) coverageStatus = 'ambiguous';
  return {
    employee_id: p.employee_id, name: p.name, email: p.email, role: p.role,
    current_project: p.current_project, availability_status: p.availability_status,
    coverage_status: coverageStatus, conflicts, ambiguous,
  };
});

return [{ json: {
  request: req,
  extraction: ext,
  employee_found: !!employee,
  employee,
  requested_start: reqStart,
  requested_end: reqEnd,
  dates_ok: datesOk,
  peers: peerResults,
  excel_rows_read: rows.length,
  excel_rows_raw: rows,
} }];

const a = $input.first().json;
const emp = a.employee;
const peers = a.peers || [];
const conflicts = peers.flatMap(p => p.conflicts);
const available = peers.filter(p => p.coverage_status === 'available');
const ambiguousPeers = peers.filter(p => p.coverage_status === 'ambiguous');

let decision;
let reason;
let coverage = false;

if (!a.employee_found) {
  decision = 'manual_review';
  reason = 'employee_not_found';
} else if (!a.dates_ok) {
  decision = 'missing_information';
  reason = 'dates_not_determined';
} else if (!emp.role || !String(emp.role).trim()) {
  decision = 'manual_review';
  reason = 'profile_missing';
} else if (peers.length === 0) {
  decision = 'manual_review';
  reason = 'no_same_profile_employees';
} else if (available.length > 0) {
  decision = 'approved';
  reason = 'coverage_available';
  coverage = true;
} else if (ambiguousPeers.length > 0) {
  decision = 'manual_review';
  reason = 'ambiguous_vacation_data';
} else {
  decision = 'manual_review';
  reason = 'coverage_conflict';
}

return [{ json: {
  employee: emp ? emp.name : (a.extraction.employee_name || a.request.sender_name || ''),
  email: emp ? emp.email : a.request.sender_email,
  profile: emp ? emp.role : null,
  requested_start: a.requested_start,
  requested_end: a.requested_end,
  same_profile_employees: peers.map(p => ({ name: p.name, email: p.email, coverage_status: p.coverage_status })),
  conflicts,
  coverage_available: coverage,
  available_coverage_employees: available.map(p => p.name),
  ambiguous_records: ambiguousPeers.map(p => ({ name: p.name, details: p.ambiguous })),
  decision,
  reason,
  extraction_notes: a.extraction.notes || '',
  message_id: a.request.message_id,
  thread_id: a.request.thread_id,
  original_subject: a.request.subject,
  original_body: a.request.body,
  audit: {
    employee_record: emp,
    same_profile_detail: peers,
    extraction: a.extraction,
    excel_rows_read: a.excel_rows_read,
    decided_at: new Date().toISOString(),
  },
} }];

